<?php
$id=(int)($_GET['id']??0);$q=$id?one('SELECT * FROM shop_quotes WHERE id=?',[$id]):null;$requestId=(int)($_GET['anfrage']??$q['request_id']??0);$request=$requestId?one('SELECT r.*,c.email FROM shop_requests r JOIN customers c ON c.id=r.customer_id WHERE r.id=?',[$requestId]):null;
if($id && !$q):http_response_code(404);empty_state('mail','Angebot nicht gefunden','Bitte wähle ein Angebot aus der Liste.');elseif($request):
$p=one('SELECT * FROM shop_products WHERE slug=?',[$request['product_slug']]);$base=$q?json_decode($q['profile'],true):(json_decode($request['configuration'],true)['module_configuration']['profile']??automation_profile((int)$p['id'])['settings']??[]);$provider=package_provider($p['category']);$automatic=$q?$q['provider']!=='manual':false;
?>
<a class="back-link" href="/admin/anfragen?id=<?= $requestId ?>">← Anfrage <?= e($request['reference']) ?></a><p>Kunde: <?= e($request['email']) ?></p>
<?php if($q): ?><section class="panel form-panel"><?php quote_details($q,true); ?><?php if($q['status']==='draft'): ?><hr><form method="post" data-confirm="Dieses Angebot verbindlich veröffentlichen und dem Kunden den Zahlungslink per E-Mail senden?"><?= csrf() ?><input type="hidden" name="action" value="quote_publish"><input type="hidden" name="quote_id" value="<?= $id ?>"><button class="button button-teal">Angebot veröffentlichen & Zahlungslink senden <?= icon('mail') ?></button><p class="small muted">Zuerst den Entwurf unten speichern. Der Versand verwendet ausschließlich die gespeicherten Angaben.</p></form><?php endif ?><?php if(in_array($q['status'],['draft','sent'],true) && !$q['order_id']): ?><form method="post" data-confirm="Dieses Angebot zurücknehmen? Der Zahlungslink wird ungültig."><?= csrf() ?><input type="hidden" name="action" value="quote_cancel"><input type="hidden" name="quote_id" value="<?= $id ?>"><button class="text-button">Angebot zurücknehmen</button></form><?php endif ?></section><?php endif ?>
<?php if(!$q || $q['status']==='draft'): ?>
<section class="panel form-panel admin-form"><h2>Angebotsentwurf</h2><form method="post" data-package-editor><?= csrf() ?><input type="hidden" name="action" value="quote_save"><input type="hidden" name="request_id" value="<?= $requestId ?>"><input type="hidden" name="quote_id" value="<?= (int)($q['id']??0) ?>"><input type="hidden" name="category" value="<?= e($p['category']) ?>"><label class="field"><span>Leistungsname</span><input name="title" maxlength="120" required value="<?= e($_POST['title']??$q['title']??$request['product_name']) ?>"></label><div class="form-grid"><label class="field"><span>Nettopreis in Euro (zzgl. 19 % MwSt.)</span><input name="net_price" inputmode="decimal" data-net-price required value="<?= e($_POST['net_price']??(isset($q)?number_format($q['net_cents']/100,2,',',''):'')) ?>"></label><label class="field"><span>Abrechnungszeitraum</span><select name="billing"><?php foreach(['once'=>'Einmalig','month'=>'Monatlich','quarter'=>'Alle 3 Monate','halfyear'=>'Alle 6 Monate','year'=>'Jährlich'] as $key=>$caption): ?><option value="<?= $key ?>" <?= ($_POST['billing']??$q['billing']??'once')===$key?'selected':'' ?>><?= $caption ?></option><?php endforeach ?></select></label><label class="field"><span>Gültig bis</span><input type="date" name="expires" required value="<?= e($_POST['expires']??(isset($q)?substr($q['expires_at'],0,10):date('Y-m-d',time()+14*86400))) ?>"></label></div><p data-tax-preview class="price-preview" aria-live="polite"></p><?php contract_policy_fields($base['contract_policy']??product_contract_policy($p)); ?><label class="field"><span>Leistung, Laufzeit und Kündigung</span><textarea name="contract_text" maxlength="2000" rows="7" required><?= e($_POST['contract_text']??$base['contract_text']??'') ?></textarea></label>
<?php foreach(['provisioning_notice'=>'Bereitstellungshinweis','dns_notice'=>'DNS-Hinweis'] as $key=>$caption): ?><label class="field"><span><?= $caption ?></span><textarea name="<?= $key ?>" maxlength="1000" rows="3" placeholder="Leer = Standard aus Shop-Einstellungen"><?= e($_POST[$key]??$q[$key]??'') ?></textarea></label><?php endforeach ?>
<?php if($provider!=='manual'): ?><label class="checkbox-field"><input type="checkbox" name="automatic" <?= ($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['automatic']):$automatic)?'checked':'' ?>><span>Nach bestätigter Zahlung automatisch über <?= e(provider_label($provider)) ?> bereitstellen</span></label><p class="small muted">Ohne Haken erfolgt die Einrichtung persönlich. Du bestätigst sie anschließend unter Bestellungen.</p><fieldset><legend>Ausstattung bei automatischer Bereitstellung</legend><div class="form-grid"><?php foreach(automation_fields($provider) as $key=>[$caption,$type,$default]):$value=$_POST['automation'][$provider][$key]??$base[$key]??$default; ?><label class="field"><span><?= e($caption) ?></span><?php if($type==='json'): ?><textarea name="automation[<?= $provider ?>][<?= $key ?>]" rows="4"><?= e(is_array($value)?json_encode($value,JSON_PRETTY_PRINT):$value) ?></textarea><?php elseif($type==='checkbox'): ?><input type="checkbox" name="automation[<?= $provider ?>][<?= $key ?>]" value="1" <?= $value?'checked':'' ?>><?php else: ?><input name="automation[<?= $provider ?>][<?= $key ?>]" type="<?= $type ?>" value="<?= e($value) ?>" <?= $type==='number'?'min="0"':'' ?>><?php endif ?></label><?php endforeach ?></div><?php if($provider==='ovh'): ?><label class="checkbox-field"><input type="checkbox" name="ovh_purchase_ack" <?= !empty($base['ovh_purchase_ack'])?'checked':'' ?>><span>Kostenpflichtige OVH-Domainbestellung nach bestätigter Zahlung bis zur angegebenen Einkaufspreisgrenze freigeben.</span></label><?php endif ?></fieldset><?php endif ?><button class="button button-teal">Entwurf speichern <?= icon('check') ?></button></form></section>
<?php else: ?><p class="small muted">Veröffentlichte Angebote bleiben unverändert. Neue Konditionen erfordern einen neuen Entwurf.</p><a class="button button-outline" href="/admin/angebote?anfrage=<?= $requestId ?>">Neuen Entwurf erstellen <?= icon('plus') ?></a><?php endif ?>
<?php else: ?><div class="info-box"><?= icon('mail') ?><span>Öffne eine Kundenanfrage und wähle „Angebot erstellen“, um einen persönlichen Preis und Zahlungslink vorzubereiten.</span></div><a class="button button-outline" href="/admin/anfragen">Zu den Anfragen <?= icon('arrow') ?></a><?php endif ?>
<?php $quotes=all('SELECT q.*,c.email FROM shop_quotes q JOIN customers c ON c.id=q.customer_id ORDER BY q.id DESC LIMIT 200'); ?>
<section class="panel"><div class="panel-title"><h2>Alle Angebote</h2></div><?php if(!$quotes):empty_state('mail','Noch keine Angebote','Persönliche Angebote erscheinen hier nach dem Speichern.');else: ?><div class="table-scroll"><table><thead><tr><th>Angebot / Kunde</th><th>Netto / Brutto</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($quotes as $row): ?><tr><td><?= e($row['title']) ?><small><?= e($row['email']) ?></small></td><td><?= money($row['net_cents']) ?> / <?= money($row['gross_cents']) ?></td><td><?= e(quote_status($row)) ?></td><td><a class="text-link" href="/admin/angebote?id=<?= (int)$row['id'] ?>">Öffnen <?= icon('arrow') ?></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
